    def quickselect(arr, low, high, k):
        if low == high:
            return arr[low]

        pivot = arr[low]
        i = low
        j = high

        while i <= j:
            while arr[i] < pivot:
                i += 1
            while arr[j] > pivot:
                j -= 1
            if i <= j:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
                j -= 1

        # Partition
        pivot_index = j
        if k <= pivot_index:
            return quickselect(arr, low, pivot_index - 1, k)
        else:
