    stack = []
    for token in tokens:
        if token in variables:
            # Variable lookup
            value = variables[token]
            stack.append(value)
        elif token in '+-*/':
            # Operator processing
            if len(stack) < 2:
                # Not enough operands for the operator
                return None
            right = stack.pop()
            left = stack.pop()

            if token == '+':
                result = left + right
            elif token == '-':
                result = left - right
            elif token == '*':
                result = left * right
            elif token == '/':
                if right == 0:
                    return None  # Division by zero
                result = left / right
            else:
                return None  # Unknown operator

            stack.append(result)
        else:
            # Unknown token
            return None

    # If stack is empty, expression is invalid
    if not stack:
        return None

    # Return the final result
    return stack[-1]

