def convert_to_hsv(r, g, b):
    # Normalize values to [0, 1]
    r, g, b = r/255.0, g/255.0, b/255.0

    # Find max, min, and delta
    max_val = max(r, g, b)
    min_val = min(r, g, b)
    delta = max_val - min_val

    # Value (V)
    v = max_val

    # Saturation (S)
    if v == 0:
        s = 0.0
    else:
        s = delta / v

    # Hue (H)
    if s == 0:
        h = 0.0
    else:
        if delta == 1.0:
            h = 0.0
        elif max_val == r:
            h = (g - b) / delta
        elif max_val == g:
            h = (2.0 + (b - r) / delta)
        else:  # max_val == b
            h = (2.0 + (r - g) / delta)

        # Adjust h to be in [0, 1)
        if h < 0:
            h += 1.0

    # Convert hue to degrees and normalize to [0, 360)
