        return True
    if n % 2 == 0:
        return False

    # Write n-1 as 2^r * d with d odd
    r, d = 0, n - 1
    while d % 2 == 0:
        r += 1
        d //= 2

    # Choose random bases a in [2, n-2]
    import random
    bases = [random.randint(2, n - 3) for _ in range(k)]

    # Fast exponentiation modulo m
    def mod_pow(a, e, m):
        result = 1
        a = a % m
        while e > 0:
            if e % 2 == 1:
                result = (result * a) % m
            a = (a * a) % m
            e //= 2
        return result

