def largestRectangleArea(heights):
    if not heights:
        return 0

    n = len(heights)
    left = [0] * n
    right = [0] * n
    stack = []

    # Compute left boundary for each bar
    for i in range(n):
        while stack and heights[stack[-1]] >= heights[i]:
            stack.pop()
        if not stack:
            left[i] = 0
        else:
            left[i] = stack[-1] + 1
        stack.append(i)

    # Clear stack and compute right boundary
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and heights[stack[-1]] >= heights[i]:
            stack.pop()
        if not stack:
            right[i] = n - 1
        else:
            right[i] = stack[-1] - 1
        stack.append(i)

    max_area = 0
    for i in range(n):
        area = heights[i] * (right[i] - left[i] + 1)
        if area > max_area:
            max_area = area

    return max_area
