    if not nums:
        return 1

    # Filter out non-positive numbers and sort them
    positives = sorted([x for x in nums if x > 0])

    # If there are no positive numbers, the smallest missing is 1
    if not positives:
        return 1

    # The smallest missing positive must be in the range [1, len(positives) + 1]
    expected = 1
    for num in positives:
        if num == expected:
            expected += 1
        else:
            # All numbers from 1 to expected-1 are present, so the next missing is expected
            return expected

