def find_prime_factors(num):
    if num <= 1:
        return []

    factors = []

    # Handle factor 2 separately
    while num % 2 == 0:
        factors.append(2)
        num //= 2

    # Check odd factors from 3 upwards
    i = 3
    while i * i <= num:
        while num % i == 0:
            factors.append(i)
            num //= i
        i += 2

    # If remaining num is greater than 1, it's a prime factor
    if num > 1:
        factors.append(num)

    return factors

